/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var isNonnegativeNumber = require( '@stdlib/assert/is-nonnegative-number' ).isPrimitive;
var format = require( '@stdlib/string/format' );


// MAIN //

/**
* Sets the rendering mode.
*
* @private
* @param {string} value - string indicate the order of the category in plot
* @throws {TypeError} must be a boolean
* @throws {Error} must be a valid string indicate the order type
*/
function set( value ) {
	if ( !isNonnegativeNumber( value ) ) {
		throw new TypeError( format( 'invalid assignment. `%s` must be a number. Value: `%s`.', 'categary label width', value ) );
	}
	if ( value !== this._barObj.gap ) {
		this._barObj.gap = value;
		if ( !this._quiet ) {
			this.emit( 'change' );
		}
	}
}


// EXPORTS //

module.exports = set;
